"""Derive SkyyZones/build_skyyzones_0.3.3.py from SkyyZones/build_skyyzones_0.3.2.py (the tools/deploy_set.py SET pin, generated by
tools/zones_0_3_2_patch.py - never re-run that one for this). Edit THIS patch, never the generated script. Every anchor is asserted; at the
end every change is undone on a copy and compared with 0.3.2 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/zones_0_3_3_patch.py   then   python SkyyZones/build_skyyzones_0.3.3.py   (never --deploy)
Harness: python SkyyZones/test_skyyzones_0.3.3.py [--keep]

0.3.3 = HOTFIX for Skyy's test (2026-10-27): "chess is locked apparently" - a chest in a Golden Steppes structure in the zone world
skywynn_zones2 (x -4979) showed "Press F to open", the use was refused with "That is locked in this area." (SkyyZones' LOCKED note).
CAUSE (read from the 0.3.2 code): ZRules.decide answered every CONTAINER / FURNACE use with
    if (act == CONTAINER) return top != null && top.fCont ? ALLOW : LOCKED;      (FURNACE the same with fFurn)
- with NO region at the spot of a protected world, containers + furnaces were ALWAYS locked. Skyy's live config has
zones.worlds=skywynn_zones2 and zones.gatherWorlds=skywynn_zones2 with NO regions, so every world-generated / structure / dungeon chest
(SkyyExploration's per-profile loot chests, chests.perProfile) and every furnace / processing bench of a structure in the zone world was
locked. Since 0.3.0's whole-island gathering layer turned the zone world into a protected (gathering) world.
FIX: in a whole-island GATHERING world (ZCfg.gatherWorld), with no region at the spot, chests and furnaces OPEN by default - two new
Server Setup rows (Zones -> Protection), both default ON:
    gather.containers  "Gathering world: chests open"   - world / structure / dungeon chests outside regions (SkyyExploration's
                                                          per-profile loot chests need this)
    gather.furnaces    "Gathering world: furnaces open" - furnaces / processing benches placed by the world (structures, camps). Players
                                                          cannot place a block there (NO_PLACE; only Scaffolding), so every bench there
                                                          is a world one - using it changes no block and takes nothing from anyone.
Unchanged on purpose: a REGION keeps its own flags (a town without 'containers' still locks its chests; a skyblock region the same - draw
'flags containers' for an open camp); a SAFE zone is not a protection layer (0.3.2) - so inside it the gathering world's rows apply; a
protected world that is NOT a gathering world keeps the 0.3.2 FULL default (locked); a gathering world locked FULL by a broken region
line (ZCfg.LOCKW, fail closed) keeps its chests locked too; player islands (skyy-island-*) and shard worlds (skyy-shard-*) are never
gathering worlds (ZCfg.gatherWorld skips them) - unaffected. Both rows off = exactly 0.3.2.
SkyyExploration 0.3.4 (read only): its PcUseSys (UseBlockEvent$Pre) returns at once when the event is already cancelled - a LOCKED from
SkyyZones' ZGuardUse (also UseBlockEvent$Pre) therefore also stopped the per-profile copy from opening. With ALLOW SkyyZones never cancels,
so PcCore.intercept runs in either system order and opens this profile's copy (it cancels the vanilla open itself).
NEW CONFIG KEYS ONLY (no line changed) = no one-time migration (PROJECT-RULES 4): a file without the keys reads the default (true).
/zones info: the verdict line now shows "Chests: ... | Furnaces: ...".
ROLLBACK to 0.3.2: just the jar - the two keys are ignored by 0.3.2 (chests + furnaces outside regions of the zone world lock again).
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

P = G.Patch(os.path.join(ROOT, "SkyyZones", "build_skyyzones_0.3.2.py"), os.path.join(ROOT, "SkyyZones", "build_skyyzones_0.3.3.py"))
assert P.has('VERSION = "0.3.2"\n') and P.has("tools/zones_0_3_2_patch.py") and P.has("ZNoSpawn") and not P.has("GCONT"), \
    "not the generated SkyyZones 0.3.2"
SYS0, CMD0 = P.s.count("registerSystem("), P.s.count("registerCommand(")

# ---- header + version
P.rep('''"""SkyyZones 0.3.2 - build script. GENERATED by tools/zones_0_3_2_patch.py from build_skyyzones_0.3.1.py (the SET pin, generated by
tools/zones_0_3_1_patch.py <- 0.3.0 <- 0.2.2 <- 0.2.1 <- 0.2.0 <- the hand-written 0.1.0) - edit the patch, not this file.
Run: python SkyyZones/build_skyyzones_0.3.2.py -> SkyyZones/SkyyZones-0.3.2.jar; harness: python SkyyZones/test_skyyzones_0.3.2.py
''', '''"""SkyyZones 0.3.3 - build script. GENERATED by tools/zones_0_3_3_patch.py from build_skyyzones_0.3.2.py (the SET pin, generated by
tools/zones_0_3_2_patch.py <- 0.3.1 <- 0.3.0 <- 0.2.2 <- 0.2.1 <- 0.2.0 <- the hand-written 0.1.0) - edit the patch, not this file.
Run: python SkyyZones/build_skyyzones_0.3.3.py -> SkyyZones/SkyyZones-0.3.3.jar; harness: python SkyyZones/test_skyyzones_0.3.3.py
NEW IN 0.3.3 (hotfix, Skyy 2026-10-27 "chess is locked apparently"; details + ROLLBACK: tools/zones_0_3_3_patch.py): in a whole-island
  gathering world, chests + furnaces with no region at the spot OPEN by default (Server Setup rows gather.containers / gather.furnaces,
  both on); regions keep their own flags, other protected worlds stay locked.
''')
P.rep('VERSION = "0.3.2"\n', 'VERSION = "0.3.3"\n')

# ---- config.properties default text (a fresh file; an existing file without the keys reads true - no migration)
P.rep('''    "gather.types=" + GATHER_TYPES,
''', '''    "gather.types=" + GATHER_TYPES,
    "# 0.3.3 gather.containers / gather.furnaces = in a gathering world, outside regions: world chests / world furnaces + benches open",
    "# (structure + dungeon loot chests). Regions keep their own flags (a town without 'containers' stays locked).",
    "gather.containers=true",
    "gather.furnaces=true",
''')

# ---- ZCfg fields + load
P.rep('''          "public static volatile boolean NOSPAWN = true;", "public static volatile String WPSRC = null;",''',
      '''          "public static volatile boolean NOSPAWN = true;", "public static volatile String WPSRC = null;",
          "public static volatile boolean GCONT = true;", "public static volatile boolean GFURN = true;",   # 0.3.3''')
P.rep('''  GATHERW = str(p.getProperty("zones.gatherWorlds"), "", 400);
''', '''  GATHERW = str(p.getProperty("zones.gatherWorlds"), "", 400);
  GCONT = bool(p.getProperty("gather.containers"), true);   // 0.3.3
  GFURN = bool(p.getProperty("gather.furnaces"), true);
''')
# 0.3.3: chests / furnaces with no region at the spot open in a gathering world (row on) - never in a world locked FULL by a bad region line
P.rep('''# fail closed: a gathering world is ALWAYS protected''', '''# 0.3.3: no region at the spot of a gathering world - may a chest (furn false) / furnace (furn true) be used? (fail closed: LOCKW = no)
M(cfg, r"""
public static boolean gatherOpen(String w, boolean furn) {
  if (!(furn ? GFURN : GCONT)) return false;
  if (!gatherWorld(w)) return false;
  return !LOCKW.contains(w.toLowerCase());
}""")
# fail closed: a gathering world is ALWAYS protected''')

# ---- the decision
P.rep('''  if (act == CONTAINER) return top != null && top.fCont ? ALLOW : LOCKED;
  if (act == FURNACE) return top != null && top.fFurn ? ALLOW : LOCKED;
''', '''  if (act == CONTAINER) return (top != null ? top.fCont : @PKG@.ZCfg.gatherOpen(w, false)) ? ALLOW : LOCKED;   // 0.3.3
  if (act == FURNACE) return (top != null ? top.fFurn : @PKG@.ZCfg.gatherOpen(w, true)) ? ALLOW : LOCKED;
''')
P.rep('''# 0.3.0 (spec 1.1): no region in a whole-island gathering world = SKYBLOCK with gather.types;''',
      '''# 0.3.3: no region in a gathering world -> chests / furnaces follow gather.containers / gather.furnaces (default open); a region keeps its flags
# 0.3.0 (spec 1.1): no region in a whole-island gathering world = SKYBLOCK with gather.types;''')

# ---- /zones info: furnaces verdict too
P.rep('''      + " | Chests: " + @PKG@.ZRules.verdict(@PKG@.ZRules.decide(ix, wn, pw, p[0], p[1], p[2], @PKG@.ZRules.CONTAINER, id)));''',
      '''      + " | Chests: " + @PKG@.ZRules.verdict(@PKG@.ZRules.decide(ix, wn, pw, p[0], p[1], p[2], @PKG@.ZRules.CONTAINER, id))
      + " | Furnaces: " + @PKG@.ZRules.verdict(@PKG@.ZRules.decide(ix, wn, pw, p[0], p[1], p[2], @PKG@.ZRules.FURNACE, id)));''')

# ---- Server Setup rows (Zones -> Protection, after gather.types)
P.rep('''     "field:ZCfg.GTYPES@config.properties:gather.types;check=ZCfg.checkGTypes"),
''', '''     "field:ZCfg.GTYPES@config.properties:gather.types;check=ZCfg.checkGTypes"),
    # 0.3.3 hotfix (Skyy 2026-10-27 "chess is locked apparently")
    ("gather.containers", "Gathering world: chests open", "zones", "bool", "true", "", "", "", "", "live",
     "Outside regions there: world, structure + dungeon chests open. Regions use their own flags.",
     "field:ZCfg.GCONT@config.properties:gather.containers"),
    ("gather.furnaces", "Gathering world: furnaces open", "zones", "bool", "true", "", "", "", "", "live",
     "Outside regions there: furnaces + benches built by the world can be used (players can't place).",
     "field:ZCfg.GFURN@config.properties:gather.furnaces"),
''')

assert P.s.count("registerSystem(") == SYS0 and P.s.count("registerCommand(") == CMD0, "0.3.3 adds no system, no command"
P.finish()
